test.source:

enum Planet {
  earth(5972, 6371),
  mars(642, 3389);

  final int mass;
  final int radius;

  const Planet(this.mass, this.radius);

  int get diameter => this.radius * 2;

  int get density {
    return this.mass ~/ this.radius;
  }

  String describe() {
    return '${this.name}:${this.diameter}';
  }
}

int run() {
  var p = Planet.mars;
  return p.diameter + Planet.earth.density + Planet.values.length;
}

String describe() {
  return Planet.earth.describe();
}
